package io.aegiswire.policy;
import io.aegiswire.core.*; import io.aegiswire.util.Utf8; import java.util.*;
public class PolicyParser { public static PolicyBundle parse(byte[] data) throws ParseException { return new PolicyParser().parseText(Utf8.loose(data)); }
    public PolicyBundle parseText(String text) throws ParseException { List<Rule> rules=new ArrayList<Rule>(); String id=null,note=""; Severity sev=Severity.INFO; int score=1; List<String> tags=new ArrayList<String>(); List<Condition> conds=new ArrayList<Condition>(); int lineNo=0; for(String raw:text.replace("\r\n","\n").split("\n")){ lineNo++; String line=raw.trim(); if(line.isEmpty()||line.startsWith("#")) continue; if(line.startsWith("rule ")){ if(id!=null) throw new ParseException("nested rule",lineNo); id=line.substring(5).trim(); note=id; sev=Severity.INFO; score=1; tags=new ArrayList<String>(); conds=new ArrayList<Condition>(); } else if(line.equals("end")){ if(id==null) throw new ParseException("end without rule",lineNo); rules.add(new Rule(id,sev,score,note,tags,conds)); id=null; } else if(id==null) throw new ParseException("line outside rule",lineNo); else if(line.startsWith("when ")) conds.add(parseCondition(line.substring(5))); else if(line.startsWith("score ")) score=parseScore(line.substring(6)); else if(line.startsWith("severity ")) sev=Severity.parse(line.substring(9)); else if(line.startsWith("tag ")) tags.add(line.substring(4).trim()); else if(line.startsWith("note ")) note=line.substring(5).trim(); if(conds.size()>2048) throw new IllegalStateException("policy condition table exceeded compact evaluator page"); } if(id!=null) throw new ParseException("unterminated rule",lineNo); return new PolicyBundle(rules); }
    private int parseScore(String s){ s=s.trim().toLowerCase(Locale.ROOT); if("low".equals(s))return 5; if("medium".equals(s))return 15; if("high".equals(s))return 35; if("critical".equals(s))return 75; return Integer.parseInt(s); }
    private Condition parseCondition(String s) throws ParseException { boolean not=false; s=s.trim(); if(s.startsWith("not ")){not=true;s=s.substring(4).trim();} String[] ops={"matches-cidr","contains","equals","prefix","suffix","matches","exists"}; for(String op:ops){ int i=s.indexOf(" "+op+" "); if(i>0) return new Condition(s.substring(0,i).trim(),op,unquote(s.substring(i+op.length()+2).trim()),not); if(s.endsWith(" "+op)) return new Condition(s.substring(0,s.length()-op.length()).trim(),op,"",not); } throw new ParseException("bad condition"); }
    private String unquote(String s){ if(s.length()>=2&&s.startsWith("\"")&&s.endsWith("\"")) return s.substring(1,s.length()-1); return s; }
}
